  "stuSess.penaltyChoiceRefundDesc": "रिफ़ंड (€{amount}) के लिए info@tutlio.lt पर संपर्क करें। यदि आपने कार्ड से भुगतान किया था, तो Stripe से रिफ़ंड अपने-आप शुरू हो सकता है।",
  "stuSess.creditAvailable": "उपलब्ध क्रेडिट",
  "stuSess.payWithCredit": "क्रेडिट से भुगतान करें",
  "stuSess.creditAppliedSuccess": "आपके बैलेंस में €{amount} का क्रेडिट जुड़ गया है और अगली क्लास में अपने-आप लागू होगा।",
  "stuSess.refundContactNote": "रिफ़ंड के लिए कृपया <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a> पर संपर्क करें।",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">कोई सवाल या समस्या है? <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a> पर संपर्क करें।</p><p class=\"font-semibold text-emerald-900\">Stripe से आपका रिफ़ंड शुरू कर दिया गया है।</p><p class=\"text-emerald-800 mt-1\">कार्ड के रिफ़ंड आमतौर पर लगभग <strong>5–10 कार्यदिवसों</strong> में मिलते हैं (बैंक के अनुसार समय बदल सकता है)। सामान्य समय-सीमा में रिफ़ंड न मिले तो <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a> पर ईमेल करें।</p>",
  "stuSess.refundSuccessManualTutor": "<p>लगता है कि इस क्लास का भुगतान Tutlio Stripe से नहीं हुआ था (जैसे बैंक ट्रांसफ़र या नकद भुगतान)। यहाँ स्वचालित रिफ़ंड उपलब्ध नहीं है।</p><p class=\"mt-2\">रिफ़ंड की व्यवस्था के लिए अपने ट्यूटर <strong>{tutor}</strong> से संपर्क करें — अपनी बुकिंग में दिए या ट्यूटर से सीधे मिले ईमेल अथवा संपर्क विवरण का इस्तेमाल करें।</p>",
  "stuSess.refundSuccessManualOrg": "<p>लगता है कि इस क्लास का भुगतान Tutlio Stripe से नहीं हुआ था (जैसे बैंक ट्रांसफ़र या नकद भुगतान)। यहाँ स्वचालित रिफ़ंड उपलब्ध नहीं है।</p><p class=\"mt-2\">आप एक संस्था के माध्यम से पढ़ते हैं, इसलिए <strong>संस्था के एडमिन</strong> से संपर्क करें (अपने ट्यूटर या संस्था के प्रकाशित संपर्क विवरण के ज़रिए)।</p>",
