  "landing.heroSubtitle": "बेहतर ट्यूशन प्रबंधन से रोज़मर्रा का काम सुव्यवस्थित करें, बेहतर फ़ैसले लें और कार्यकुशलता बढ़ाएँ।",
  "landing.heroCta": "मुफ़्त शुरुआत करें",
  "landing.heroSpotAria": "मुख्य सुविधाओं का पूर्वावलोकन",
  "landing.heroSpot1Body": "खुद क्लास बनाएँ या विद्यार्थियों को अपने समय-स्लॉट बुक करने दें — सब कुछ एक जगह स्पष्ट रहता है।",
  "landing.heroSpot2Body": "बिखरे नोट्स भूल जाएँ — प्रतीक्षा सूची का काम स्वचालित करें और रद्द हुई क्लास से आमदनी का नुकसान घटाएँ।",
  "landing.heroMoreFeaturesCta": "और सुविधाएँ",
  "landing.trustText": "दुनिया भर के ट्यूटरों और स्कूलों का भरोसा।",
  "landing.heroLessonCount": "क्लास निर्धारित की जा चुकी हैं। जुड़ें और समय बचाएँ।",
  "landing.stepsTitle": "3 आसान चरणों में शुरुआत करें",
  "landing.stepsDesc": "अपनी प्रोफ़ाइल बनाएँ, क्लास व्यवस्थित करें और व्यवसाय बढ़ाएँ — स्मार्ट ऑटोमेशन से ट्यूशन का काम आसान बनाएँ।",
  "landing.step1Title": "अपनी प्रोफ़ाइल बनाएँ",
  "landing.step1Desc": "ट्यूटर वर्कस्पेस सेट करें, विषय, कीमतें और उपलब्धता जोड़ें। विद्यार्थियों को आमंत्रित करें ताकि सभी के पास शुरू से एक ही सही जानकारी हो।",
  "landing.step2Title": "अपनी क्लास व्यवस्थित करें",
  "landing.step2Desc": "कैलेंडर, प्रतीक्षा सूची और बुकिंग सिस्टम से क्लास व्यवस्थित करें, खाली समय भरें और अपनी समय-सारणी शुरू से अंत तक चलाते रहें।",
  "landing.step3Title": "भुगतान पाएँ और आगे बढ़ें",
  "landing.step3Desc": "भुगतान ट्रैक करें, इनवॉइस भेजें और वित्त पर नज़र रखें। स्पष्ट, सटीक डेटा से अपना व्यवसाय चलाएँ और तेज़ी से नतीजे पाएँ।",
  "landing.featuresHeading": "अपने ट्यूशन व्यवसाय को बेहतर बनाएँ — ",
  "landing.featuresHighlight": "स्मार्ट टूल्स के साथ",
  "landing.featuresSubtitle": "हमारा प्लेटफ़ॉर्म समय-सारणी बनाने, प्रबंधन करने और ट्यूशन व्यवसाय बढ़ाने के टूल देता है, ताकि आप बेहतर फ़ैसले ले सकें और कार्यकुशलता बढ़ा सकें।",
  "landing.feat.scheduling": "स्मार्ट समय-सारणी",
  "landing.feat.schedulingDesc": "विद्यार्थियों को आपके तय समय-स्लॉट बुक करने दें और अपना कैलेंडर आसानी से संभालें।",
  "landing.feat.schedulingHeading": "व्यवस्थित और बेहतर बनाएँ",
  "landing.feat.schedulingHighlight": "अपनी समय-सारणी",
  "landing.feat.schedulingB1": "विद्यार्थियों को आपके उपलब्ध समय-स्लॉट खुद बुक करने दें — बार-बार संदेश भेजने की ज़रूरत नहीं।",
  "landing.feat.schedulingB2": "बुकिंग की समय-सीमा और क्लास के बीच का विराम अपने-आप सेट करें।",
  "landing.feat.schedulingB3": "अपना पूरा साप्ताहिक और मासिक कैलेंडर सभी क्लास के साथ एक ही जगह देखें।",
  "landing.feat.waitlist": "प्रतीक्षा सूची सिस्टम",
  "landing.feat.waitlistDesc": "रद्द हुए समय-स्लॉट अपने-आप भरें और आमदनी का नुकसान न होने दें।",
  "landing.feat.waitlistHeading": "आमदनी का नुकसान रोकें —",
  "landing.feat.waitlistHighlight": "स्मार्ट प्रतीक्षा सूची के साथ",
  "landing.feat.waitlistB1": "विद्यार्थी अपने पसंदीदा समय की प्रतीक्षा सूची में जुड़ते हैं — कोई रद्द करता है तो सूची में अगले व्यक्ति को सूचना मिलती है।",
  "landing.feat.waitlistB2": "ज़्यादा भरे हुए क्लास स्लॉट से कम घंटे बर्बाद होते हैं और आमदनी बढ़ती है।",
  "landing.feat.waitlistB3": "सिस्टम सब कुछ अपने-आप संभालता है — आप सिर्फ़ पढ़ाएँ।",
  "landing.feat.payments": "भुगतान और वित्त",
  "landing.feat.paymentsDesc": "Stripe भुगतान, इनवॉइस और मासिक वित्तीय सारांश एक ही जगह।",
  "landing.feat.paymentsHeading": "नज़र रखें और प्रबंधित करें",
  "landing.feat.paymentsHighlight": "अपने वित्त",
  "landing.feat.paymentsB1": "Stripe से ऑनलाइन भुगतान स्वीकार करें — विद्यार्थी एक क्लिक में भुगतान कर सकते हैं।",
  "landing.feat.paymentsB2": "एक नज़र में देखें कि किसने भुगतान किया, किसका बाकी है और आपका कुल मासिक राजस्व कितना है।",
  "landing.feat.paymentsB3": "पूरी हुई क्लास के आधार पर इनवॉइस अपने-आप बनाएँ और भेजें।",
  "landing.feat.reminders": "स्मार्ट रिमाइंडर",
