  "landing.feat.remindersB2": "बकाया भुगतान की सूचनाएँ आपके कुछ किए बिना भेजी जाती हैं।",
  "landing.feat.remindersB3": "अलग-अलग घटनाओं और विद्यार्थी प्रकारों के लिए ईमेल के नियम तय करें।",
