  "pwa.guideSubtitle": "Tutlio को अपने फ़ोन पर सामान्य ऐप की तरह इस्तेमाल करें",
  "pwa.guideIntro": "Tutlio को अपने फ़ोन की होम स्क्रीन पर जोड़कर सामान्य ऐप की तरह इस्तेमाल कर सकते हैं — पूरी स्क्रीन और तुरंत एक्सेस के साथ।",
  "pwa.iosStep1": "Safari में Tutlio खोलें और स्क्रीन के नीचे शेयर बटन (तीर वाला चौकोर आइकन) पर टैप करें।",
  "pwa.iosStep2": "नीचे स्क्रॉल करें और ‘होम स्क्रीन पर जोड़ें’ (Add to Home Screen) पर टैप करें।",
