  "pwa.androidStep1": "Chrome में Tutlio खोलें और ऊपर दाईं ओर तीन बिंदुओं वाले मेन्यू (⋮) पर टैप करें।",
  "pwa.androidStep2": "‘होम स्क्रीन पर जोड़ें’ (Add to Home screen) या ‘ऐप इंस्टॉल करें’ (Install app) पर टैप करें।",
  "pwa.androidStep3": "पुष्टि करें — Tutlio का आइकन आपकी होम स्क्रीन पर आ जाएगा।",
  "pwa.guideTip": "इंस्टॉल करने के बाद बेहतर अनुभव के लिए Tutlio को होम स्क्रीन से खोलें। यह सामान्य ऐप की तरह काम करता है!",
