  "quiz.info.custom-fit.company.point3": "हमारी टीम के साथ ज़रूरत की समीक्षा करें और बनाने से पहले कस्टम काम का स्पष्ट दायरा तय करें।",
  "quiz.info.custom-fit.school.point3": "हमारी टीम के साथ ज़रूरत की समीक्षा करें और बनाने से पहले कस्टम काम का स्पष्ट दायरा तय करें।",
