  "quiz.info.custom-fit.school.body": "हर स्कूल के अनुबंध, भुगतान, रिपोर्ट और प्रशासन के अपने विवरण होते हैं। Tutlio आपकी अहम ज़रूरतों के लिए कस्टम सुविधाओं का दायरा तय कर सकता है।",
